sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var coverageEngine = new TestReachCoverageEngine();
    var result = coverageEngine.analyzeArtifact(current.getUniqueValue(), 'business_rule');

    if (result.tested_by.length > 0) {
        var testNames = [];
        for (var i = 0; i < result.tested_by.length; i++) {
            testNames.push(result.tested_by[i].test_name);
        }
        gs.addInfoMessage(
            'TestReach: This business rule is covered by ' + result.tested_by.length +
            ' ATF test(s): ' + testNames.join(', ') +
            '. If you modify the condition or script, review these tests.'
        );
    } else {
        gs.addInfoMessage(
            'TestReach: This business rule has ZERO ATF test coverage. ' +
            'Consider generating a test skeleton via the "Generate ATF Test Stub" UI Action.'
        );
    }

})(current, previous);

(function executeRule(current, previous /*null when async*/) {

    // Validate risk_score is 0-100
    var riskScore = parseInt(current.getValue('risk_score') || 0, 10);
    if (riskScore < 0 || riskScore > 100) {
        current.setValue('risk_score', Math.max(0, Math.min(100, riskScore)));
        gs.warn('TestReach: Risk score clamped to valid range 0-100. Original value was outside bounds.');
    }

    // Validate app_scope is not empty
    var appScope = current.getValue('app_scope') || '';
    if (!appScope) {
        gs.addErrorMessage('TestReach: app_scope is required for risk score records.');
        current.setAbortAction(true);
        return;
    }

    // Validate upgrade_target is not empty
    var upgradeTarget = current.getValue('upgrade_target') || '';
    if (!upgradeTarget) {
        gs.addErrorMessage('TestReach: upgrade_target is required for risk score records.');
        current.setAbortAction(true);
        return;
    }

    // Auto-set computed_ts if not provided
    if (!current.getValue('computed_ts')) {
        current.setValue('computed_ts', new GlideDateTime().getValue());
    }

})(current, previous);
